// Original schematic placeholders. No licensed character artwork or permanent PIP design.
export const pipPalette=[{id:'standard',name:'Standard cream',color:'#fff1b8'},{id:'red',name:'Alex red',color:'#cf4348'},{id:'green',name:'Malik green',color:'#38864a'},{id:'pink',name:'Maya pink',color:'#d76a9d'},{id:'yellow',name:'Aiden yellow',color:'#edc74d'},{id:'white',name:'Kaito white',color:'#f2f2e8'},{id:'black',name:'Lucas black',color:'#303842'},{id:'orange',name:'Sumati orange',color:'#d96b24'},{id:'purple',name:'Lilja purple',color:'#8653b6'}];
export const pipGroups=[
 {id:'travel',title:'Move',icon:'🛞',parts:[{id:'hover',name:'Hover',icon:'☁️',note:'PIP floats beside me.'},{id:'wheels',name:'Rover wheels',icon:'🛞',note:'A rolling look for ground exploring.'},{id:'climber',name:'Four climbing arms',icon:'🕷️',note:'Four arms fitted. Climbing terrain comes later.'},{id:'swim',name:'Swim kit',icon:'🌊',note:'Swim gear for the Aquatic Learning Center.'}]},
 {id:'tool',title:'Science',icon:'🔬',parts:[{id:'scanner',name:'Scanner',icon:'📡',note:'Ask PIP about a discovery.'},{id:'lens',name:'Zoom lens',icon:'🔬',note:'Look at a discovery more closely.'},{id:'sampler',name:'Sample arm',icon:'🦾',note:'Find out what a sample can tell us.'},{id:'life-lens',name:'Life lens',icon:'🧬',note:'Lucas: explore a plant-cell model. Try fitted tool to zoom.'},{id:'xeno-lab',name:'Xeno lab',icon:'🪐',note:'Lucas: compare possible conditions for life beyond Earth. No alien life is confirmed.'},{id:'eco-probe',name:'Eco probe',icon:'🌱',note:'Sumati: reveal relationships between organisms and their environment.'},{id:'pattern-projector',name:'Pattern projector',icon:'🔷',note:'Lilja: explore patterns, counting and symmetry.'}]},
 {id:'eyes',title:'Eyes',icon:'👀',parts:[{id:'visor',name:'Visor',icon:'▰',note:'A friendly glowing visor.'},{id:'binocular',name:'Explorer eyes',icon:'👀',note:'Two curious lenses.'},{id:'round',name:'Round eyes',icon:'◎',note:'Two round bright eyes.'}]},
 {id:'trim',title:'Fins & wings',icon:'🪽',parts:[{id:'none',name:'No extra fins',icon:'◻',note:'Keep PIP simple.'},{id:'wings',name:'Wings',icon:'🪽',note:'Little wings for a flying buddy.'},{id:'fins',name:'Fins',icon:'🐟',note:'Streamlined fins for a rover look.'}]}
];
export function standardPip(){return {color:'standard',travel:'hover',tool:'scanner',eyes:'visor',trim:'none'}}
export function normalizePip(value={}){const c=standardPip();if(pipPalette.some(x=>x.id===value?.color))c.color=value.color;for(const g of pipGroups)if(g.parts.some(p=>p.id===value?.[g.id]))c[g.id]=value[g.id];return c}
export function attachPip(config,slot,part){const next=normalizePip(config);if(slot==='color'?pipPalette.some(p=>p.id===part):pipGroups.some(g=>g.id===slot&&g.parts.some(p=>p.id===part)))next[slot]=part;return next}
export function matchPipCrew(config,index){return attachPip(config,'color',pipPalette[index+1]?.id||'standard')}
export const pipScience={
 quartz:{title:'Quartz',formula:'SiO₂',atoms:[['Si','Silicon',1],['O','Oxygen',2]],fact:'Quartz is made of silicon and oxygen. Its atoms form a repeating crystal network.',zoom:'Look for flat crystal faces. The same tiny pattern repeats through the crystal.',sample:'Quartz can let light through. Observe its shape without scratching it.',note:'One silicon for two oxygen atoms. This is a ratio in a crystal, not a separate quartz molecule.'},
 iron:{title:'Iron-bearing mineral',formula:'Fe₃O₄',atoms:[['Fe','Iron',3],['O','Oxygen',4]],fact:'Magnetite is one example of an iron-bearing mineral. It contains iron and oxygen.',zoom:'Some iron-bearing minerals, like magnetite, are attracted to a magnet.',sample:'Try comparing materials with a magnet when the magnet experiment is available.',note:'Example: magnetite. Not every iron-bearing mineral has this formula or is magnetic.'},
 fossil:{title:'Fossil',formula:'CaCO₃',atoms:[['Ca','Calcium',1],['C','Carbon',1],['O','Oxygen',3]],fact:'A fossil is a trace or remain of ancient life. It does not have one chemical formula.',zoom:'Look for shell shapes or patterns left by something that lived long ago.',sample:'Fossils can contain different minerals. Observe gently and leave the fossil safe.',note:'Example: many shells began as calcium carbonate, CaCO₃. Fossil material can change during preservation.'}
};
export function pipAnalysis(id,tool='scanner'){const item=pipScience[id];if(!item)return null;return {...item,detail:tool==='lens'?item.zoom:tool==='sampler'?item.sample:item.fact}}
